import torch
import torch.nn as nn
import bitsandbytes as bnb
from dataclasses import dataclass
from typing import Optional

# --- MatmulLtState (bitsandbytes/autograd/_functions.py) ---
@dataclass
class MatmulLtState:
    _tile_indices: Optional[torch.Tensor] = None
    force_no_igemmlt: bool = False
    CB: Optional[torch.Tensor] = None
    CxB: Optional[torch.Tensor] = None
    SB: Optional[torch.Tensor] = None
    SCB: Optional[torch.Tensor] = None
    CxBt: Optional[torch.Tensor] = None
    SBt: Optional[torch.Tensor] = None
    CBt: Optional[torch.Tensor] = None
    subB: Optional[torch.Tensor] = None
    outlier_pool: Optional[bnb.autograd._functions.GlobalOutlierPooler] = None
    has_accumulated_gradients = False
    threshold = 0.0
    idx: Optional[torch.Tensor] = None
    is_training = True
    has_fp16_weights = True
    use_pool = False
    formatB = "row"

    def reset_grads(self):
        self.CB = None
        self.CxB = None
        self.SB = None
        self.SCB = None
        self.CxBt = None
        self.SBt = None
        self.CBt = None

# --- MatMul8bitLt (bitsandbytes/autograd/_functions.py) ---
class MatMul8bitLt(torch.autograd.Function):
    @staticmethod
    def forward(
        ctx: torch.autograd.function.FunctionCtx,
        A: torch.Tensor,
        B: torch.Tensor,
        out: Optional[torch.Tensor] = None,
        bias: Optional[torch.Tensor] = None,
        state: Optional[MatmulLtState] = None,
    ):
        state = state or MatmulLtState()
        ctx.is_empty = False
        if A.numel() == 0:
            ctx.is_empty = True
            ctx.A = A; ctx.B = B; ctx.bias = bias
            return torch.empty(A.shape[:-1] + B.shape[1:], dtype=A.dtype, device=A.device)

        input_shape = A.shape
        if A.dtype != torch.float16 and not bnb.autograd._functions._is_compiling():
            pass # warnings.warn(...)
        if len(A.shape) == 3:
            A = A.reshape(-1, A.shape[-1])

        if ctx.needs_input_grad[1]:
            CA, CAt, SCA, SCAt, outlier_cols = bnb.functional.int8_double_quant(A.to(torch.float16), threshold=state.threshold)
        else:
            CA, SCA, outlier_cols = bnb.functional.int8_vectorwise_quant(A.to(torch.float16), threshold=state.threshold)
            CAt = SCAt = None

        if state.has_fp16_weights or state.CB is None:
            is_transposed = not B.is_contiguous() and B.shape[0] == B.stride(1)
            if is_transposed: B = B.contiguous()
            state.CB, state.SCB, _ = bnb.functional.int8_vectorwise_quant(B.to(torch.float16))

        if state.threshold > 0.0:
            state.idx = outlier_cols
            output, subA = torch.ops.bitsandbytes.int8_mixed_scaled_mm(A, CA, state.CB, SCA, state.SCB, outlier_cols, bias)
        else:
            output = torch.ops.bitsandbytes.int8_scaled_mm.default(CA, state.CB, SCA, state.SCB, bias=bias, dtype=A.dtype)
            subA = None

        ctx.state = state; ctx.grad_shape = input_shape; ctx.dtype_A = A.dtype; ctx.dtype_bias = None if bias is None else bias.dtype
        if any(ctx.needs_input_grad[:2]): ctx.tensors = (CAt, subA, A); ctx.tensor_states = (SCAt, state.idx)
        else: ctx.tensors = [None, None, None]; ctx.tensor_states = (None, None); ctx.save_for_backward(None, None)

        output_shape = (*input_shape[:-1], state.CB.shape[0])
        if len(input_shape) == 3: return output.reshape(output_shape)
        return output

    @staticmethod
    def backward(ctx: torch.autograd.function.FunctionCtx, grad_output: torch.Tensor):
        if ctx.is_empty:
            bias_grad = None if ctx.bias is None else torch.zeros_like(ctx.bias)
            return torch.zeros_like(ctx.A), torch.zeros_like(ctx.B), None, bias_grad, None

        req_gradA, req_gradB, _, req_gradBias, _ = ctx.needs_input_grad
        CAt, subA, A = ctx.tensors
        SCAt, idx = ctx.tensor_states
        state: MatmulLtState = ctx.state
        grad_A = grad_B = grad_bias = None

        if req_gradBias: grad_bias = grad_output.sum(0, dtype=ctx.dtype_bias)
        if len(grad_output.shape) == 3:
            grad_output = grad_output.reshape(-1, grad_output.shape[-1]).contiguous()

        if req_gradB:
            Cgrad, _, _, SCgradt, _ = bnb.functional.int8_double_quant(grad_output.to(torch.float16))
            grad_B = torch.ops.bitsandbytes.int8_scaled_mm.default(Cgrad.t().contiguous(), CAt.t(), SCgradt, SCAt, dtype=torch.float16)
            if state.threshold > 0.0 and subA is not None and subA.numel() > 0:
                grad_B[:, idx] += torch.matmul(grad_output.t(), subA)

        if req_gradA:
            if state.CB is not None:
                CB = state.CB.to(ctx.dtype_A, copy=True).mul_(state.SCB.unsqueeze(1).mul(1.0 / 127.0))
                grad_A = torch.matmul(grad_output.to(ctx.dtype_A), CB).view(ctx.grad_shape)
            else: raise Exception("State must contain CB matrix for backward")

        return grad_A, grad_B, None, grad_bias, None

# --- matmul dispatcher (bitsandbytes/__init__.py) ---
def matmul(
    A: torch.Tensor, B: torch.Tensor, out: Optional[torch.Tensor] = None,
    state: Optional[MatmulLtState] = None, threshold=0.0, bias: Optional[torch.Tensor] = None
):
    state = state or MatmulLtState()
    if threshold > 0.0: state.threshold = threshold
    # MatMul8bitLt is used for CUDA by default. Fallback for CPU/XPU not shown here.
    return MatMul8bitLt.apply(A, B, out, bias, state)

# --- Int8Params (bitsandbytes/nn/modules.py) ---
class Int8Params(torch.nn.Parameter):
    def __new__(
        cls, data: Optional[torch.Tensor] = None, requires_grad=True, has_fp16_weights=False, CB: Optional[torch.Tensor] = None, SCB: Optional[torch.Tensor] = None
    ) -> "Int8Params":
        if data is None: data = torch.empty(0)
        obj = torch.Tensor._make_subclass(cls, data, requires_grad)
        obj.CB = CB; obj.SCB = SCB; obj.has_fp16_weights = has_fp16_weights
        return obj

    def _quantize(self, device):
        if self.has_fp16_weights: return super().to(device)
        B = self.data.contiguous().to(device=device, dtype=torch.float16)
        CB, SCB, _ = bnb.functional.int8_vectorwise_quant(B)
        self.data = CB; self.CB = CB; self.SCB = SCB
        return self

# --- Linear8bitLt (bitsandbytes/nn/modules.py) ---
class Linear8bitLt(nn.Linear):
    def __init__(
        self, input_features: int, output_features: int, bias=True, has_fp16_weights=True, threshold=0.0, index=None, device=None
    ):
        super().__init__(input_features, output_features, bias, device)
        self.state = bnb.MatmulLtState()
        self.index = index
        self.state.threshold = threshold
        self.state.has_fp16_weights = has_fp16_weights
        if threshold > 0.0 and not has_fp16_weights: self.state.use_pool = True
        self.weight = Int8Params(self.weight.data, has_fp16_weights=has_fp16_weights, requires_grad=has_fp16_weights)

    def init_8bit_state(self):
        self.state.CB = self.weight.CB; self.state.SCB = self.weight.SCB
        self.weight.CB = None; self.weight.SCB = None

    def forward(self, x: torch.Tensor):
        self.state.is_training = self.training
        if self.weight.CB is not None: self.init_8bit_state()
        if self.bias is not None and self.bias.dtype != x.dtype: self.bias.data = self.bias.data.to(x.dtype)
        out = bnb.matmul(x, self.weight, bias=self.bias, state=self.state)
        if not self.state.has_fp16_weights and self.state.CB is not None: self.weight.data = self.state.CB
        return out

# --- BitsAndBytesConfig usage example (benchmarking/int8/int8_benchmark.py) ---
from transformers import AutoModelForCausalLM, AutoTokenizer, BitsAndBytesConfig
model_name = "meta-llama/Llama-3.1-8B"
tokenizer = AutoTokenizer.from_pretrained(model_name)
input_ids = tokenizer(["Below is a question. I need an answer.\n\nExplain machine learning: "] * 8, return_tensors="pt").input_ids.to(0)
model = AutoModelForCausalLM.from_pretrained(
    model_name,
    device_map="auto",
    quantization_config=BitsAndBytesConfig(
        load_in_8bit=True,
        llm_int8_threshold=6.0,
    ),
    attn_implementation="sdpa",
    torch_dtype=torch.float16,
)
# ... model.generate(input_ids, max_new_tokens=128)

