# --- Default backend functional implementations (bitsandbytes/backends/default/ops.py) ---
# _int8_mixed_scaled_mm (mixed-precision decomposition logic)
@bnb._ops.register_kernel("bitsandbytes::int8_mixed_scaled_mm", "default")
def _(A: torch.Tensor, CA: torch.Tensor, CB: torch.Tensor, SCA: torch.Tensor, SCB: torch.Tensor, outlier_cols: Optional[torch.Tensor] = None, bias: Optional[torch.Tensor] = None) -> tuple[torch.Tensor, Optional[torch.Tensor]]:
    subB = None
    if outlier_cols is not None and outlier_cols.numel():
        subA = A[:, outlier_cols].contiguous()
        subB = (torch.ops.bitsandbytes.int8_vectorwise_dequant.default(CB[:, outlier_cols].contiguous(), SCB).to(A.dtype).t())
    else: subA = torch.empty(0, device=A.device, dtype=A.dtype)

    output = torch.ops.bitsandbytes.int8_scaled_mm.default(CA, CB, SCA, SCB, bias=bias, dtype=A.dtype)

    if subB is not None: output = output.addmm(subA, subB)
    return output, subA

# _int8_scaled_mm (combines matmul and dequantization)
@bnb._ops.register_kernel("bitsandbytes::int8_scaled_mm", "default")
def _(A: torch.Tensor, B: torch.Tensor, row_stats: torch.Tensor, col_stats: torch.Tensor, bias: Optional[torch.Tensor] = None, dtype: Optional[torch.dtype] = None) -> torch.Tensor:
    out_i32 = torch.ops.bitsandbytes.int8_linear_matmul.default(A, B)
    return torch.ops.bitsandbytes.int8_mm_dequant.default(out_i32, row_stats, col_stats, dtype=dtype or torch.float16, bias=bias)

# _int8_linear_matmul_impl (naive float32 matmul fallback for int8 matmul)
def _int8_linear_matmul_impl(A: torch.Tensor, B: torch.Tensor, out: Optional[torch.Tensor] = None):
    result = torch.matmul(A.float(), B.float().t()).to(torch.int32)
    if out is not None: result = out.copy_(result)
    return result

# _int8_vectorwise_quant (vector-wise quantization logic)
@bnb._ops.register_kernel("bitsandbytes::int8_vectorwise_quant", "default")
def _(A: torch.Tensor, threshold=0.0):
    # ... outlier masking logic if threshold > 0.0 ...
    row_stats = torch.max(A.abs(), dim=1).values.float()
    out_row = torch.round(A * (127.0 / row_stats.unsqueeze(-1))).to(torch.int8)
    # ... zero out outliers, restore outliers ...
    return out_row, row_stats, outlier_cols

